begin;
create function pg_temp.account_denied(action text,payload jsonb,actor jsonb) returns void language plpgsql as $$
begin
 begin perform public.mes_dispatch(action,payload,actor); exception when others then return; end;
 raise exception 'Expected account action % to be rejected',action;
end $$;
do $$
declare
 bootstrap jsonb; created jsonb; second jsonb; result jsonb;
 owner jsonb; member jsonb; other jsonb; saved_member jsonb; uid1 text; uid2 text;
 dept text; issue1 text; issue2 text; code text; token1 text; rows jsonb;
begin
 assert not has_function_privilege('anon','public.mes_issue_owner_activation()','execute');
 assert not has_function_privilege('authenticated','public.mes_issue_owner_activation()','execute');
 assert not has_function_privilege('service_role','public.mes_issue_owner_activation()','execute');
 assert not has_function_privilege('anon','public.mes_dispatch(text,jsonb,jsonb)','execute');
 assert not has_table_privilege('authenticated','mes_private.credentials','select');
 assert public.mes_dispatch('getDirectory','{}','{}')->>'accountMode'='password';
 perform pg_temp.account_denied('loginManagedUser','{"uid":"mes-owner"}','{}');
 perform pg_temp.account_denied('startWindowsChallenge','{"username":"hpham"}','{}');
 bootstrap:=public.mes_issue_owner_activation();
 result:=public.mes_dispatch('activateAccount',jsonb_build_object('username','hpham','activationCode',bootstrap->>'activationCode','password','short'),'{}');
 assert result->>'errorCode'='password-policy';
 result:=public.mes_dispatch('activateAccount',jsonb_build_object('username','hpham','activationCode',bootstrap->>'activationCode','password','owner-pass-123'),'{}');
 owner:=jsonb_build_object('session',result->>'sessionToken');
 assert public.mes_dispatch('getSession','{}',owner)->>'isOwner'='true';
 assert public.mes_dispatch('getSession','{}',owner)->>'requiresWindows'='false';
 insert into mes_private.sessions(hash,uid,username,expires_at) values(encode(extensions.digest(repeat('f',64),'sha256'),'hex'),'mes-owner','hpham',now()+interval '1 hour');
 perform pg_temp.account_denied('getSession','{}',jsonb_build_object('session',repeat('f',64)));
 assert public.mes_issue_owner_activation()->>'status'='already-activated';
 result:=public.mes_dispatch('activateAccount',jsonb_build_object('username','hpham','activationCode',bootstrap->>'activationCode','password','other-pass-123'),'{}');
 assert result->>'errorCode'='invalid-credentials';
 created:=public.mes_dispatch('manageUser','{"operation":"create","username":"operator.one","displayName":"Operator One","role":"owner"}',owner); uid1:=created->>'uid';
 second:=public.mes_dispatch('manageUser','{"operation":"create","username":"operator.two"}',owner); uid2:=second->>'uid';
 assert (select role='user' from mes_private.credentials where uid=uid1);
 assert (select password_hash is null and activation_hash<>created->>'activationCode' from mes_private.credentials where uid=uid1);
 result:=public.mes_dispatch('passwordLogin','{"username":"operator.one","password":"not-set-yet"}','{}'); assert result->>'errorCode'='invalid-credentials';
 result:=public.mes_dispatch('activateAccount',jsonb_build_object('username','operator.one','activationCode',created->>'activationCode','password','operator-pass-123'),'{}');
 token1:=result->>'sessionToken'; assert token1 is not null; member:=jsonb_build_object('session',token1); saved_member:=member;
 assert public.mes_dispatch('getSession','{}',member)->'user'->>'uid'=uid1;
 assert public.mes_dispatch('getSession','{}',member)->>'isOwner'='false';
 assert public.mes_dispatch('getSession','{}',member||'{"tester":true}')->'user'->>'isTester' is null;
 assert (select password_hash<>'operator-pass-123' and activation_hash is null from mes_private.credentials where uid=uid1);
 result:=public.mes_dispatch('passwordLogin','{"username":"OPERATOR.ONE","password":"operator-pass-123"}','{}'); assert result->>'sessionToken' is not null;
 result:=public.mes_dispatch('activateAccount',jsonb_build_object('username','operator.two','activationCode',second->>'activationCode','password','second-pass-123'),'{}'); other:=jsonb_build_object('session',result->>'sessionToken');
 perform pg_temp.account_denied('manageUser','{"operation":"create","username":"evil"}',member);
 perform pg_temp.account_denied('resetUserActivation',jsonb_build_object('uid',uid2),member);
 perform pg_temp.account_denied('manageUser','{"operation":"deactivate","uid":"mes-owner","active":false}',owner);
 perform public.mes_dispatch('saveProfile',jsonb_build_object('uid',uid2,'displayName','My Name','email','contact@example.com','jobTitle','OT Engineer','role','owner'),member);
 assert public.mes_dispatch('getProfile',jsonb_build_object('uid',uid2),member)->'profile'->>'displayName'='My Name';
 assert public.mes_dispatch('getProfile','{}',other)->'profile'->>'displayName'='operator.two';
 assert public.mes_dispatch('getSession','{}',member)->>'isOwner'='false';
 dept:=public.mes_dispatch('manageDirectory','{"operation":"create","type":"departments","name":"Accounts test"}',owner)->>'id';
 issue1:=public.mes_dispatch('createIssue',jsonb_build_object('reporterUid',uid1,'departmentId',dept,'process','Line 1','description','First report'),member)->>'id';
 issue2:=public.mes_dispatch('createIssue',jsonb_build_object('reporterUid',uid2,'departmentId',dept,'process','Line 2','description','Second report'),other)->>'id';
 rows:=public.mes_dispatch('read',jsonb_build_object('path','myIssues','uid',uid2),member)->'rows';
 assert jsonb_array_length(rows)=1 and rows->0->>'id'=issue1;
 assert jsonb_array_length(public.mes_dispatch('read','{"path":"issues"}',member)->'rows')=2;
 assert jsonb_array_length(public.mes_dispatch('readBundle','{"paths":[{"path":"myIssues"},{"path":"issues"}]}',member)->'snapshots'->'myIssues'->'rows')=1;
 result:=public.mes_dispatch('changePassword','{"currentPassword":"wrong","password":"replacement-pass"}',member);assert result->>'errorCode'='invalid-credentials';
 result:=public.mes_dispatch('changePassword','{"currentPassword":"operator-pass-123","password":"replacement-pass"}',member);member:=jsonb_build_object('session',result->>'sessionToken');
 perform pg_temp.account_denied('getSession','{}',saved_member);
 assert public.mes_dispatch('getSession','{}',member)->'user'->>'uid'=uid1;
 created:=public.mes_dispatch('resetUserActivation',jsonb_build_object('uid',uid1),owner);
 perform pg_temp.account_denied('getSession','{}',member);
 result:=public.mes_dispatch('passwordLogin','{"username":"operator.one","password":"replacement-pass"}','{}');assert result->>'errorCode'='invalid-credentials';
 result:=public.mes_dispatch('activateAccount',jsonb_build_object('username','operator.one','activationCode',created->>'activationCode','password','reactivated-pass'),'{}');member:=jsonb_build_object('session',result->>'sessionToken');
 perform public.mes_dispatch('manageUser',jsonb_build_object('operation','deactivate','uid',uid1,'active',false),owner);
 perform pg_temp.account_denied('getSession','{}',member);
 perform public.mes_dispatch('manageUser',jsonb_build_object('operation','deactivate','uid',uid1,'active',true),owner);
 perform pg_temp.account_denied('getSession','{}',member);
 result:=public.mes_dispatch('passwordLogin','{"username":"operator.one","password":"reactivated-pass"}','{}');member:=jsonb_build_object('session',result->>'sessionToken');
 perform public.mes_dispatch('logout','{}',member);perform pg_temp.account_denied('getSession','{}',member);
 for i in 1..10 loop
   result:=public.mes_dispatch('passwordLogin','{"username":"nonexistent","password":"invalid-pass"}','{}'); assert result->>'errorCode'='invalid-credentials';
 end loop;
 assert public.mes_dispatch('passwordLogin','{"username":"nonexistent","password":"invalid-pass"}','{}')->>'errorCode'='rate-limited';
 assert (select (data->>'count')::int=10 from mes_private.records where collection='loginRates' and id='nonexistent');
 created:=public.mes_dispatch('resetUserActivation',jsonb_build_object('uid',uid2),owner);code:=created->>'activationCode';
 created:=public.mes_dispatch('resetUserActivation',jsonb_build_object('uid',uid2),owner);
 assert public.mes_dispatch('activateAccount',jsonb_build_object('username','operator.two','activationCode',code,'password','new-second-pass'),'{}')->>'errorCode'='invalid-credentials';
 update mes_private.credentials set activation_expires=now()-interval '1 minute' where uid=uid2;
 assert public.mes_dispatch('activateAccount',jsonb_build_object('username','operator.two','activationCode',created->>'activationCode','password','new-second-pass'),'{}')->>'errorCode'='invalid-credentials';
 result:=public.mes_dispatch('getSession','{}',owner||'{"tester":true}');assert result->>'isOwner'='false' and result->'user'->>'isTester'='true';
 perform pg_temp.account_denied('manageUser','{"operation":"create","username":"tester-evil"}',owner||'{"tester":true}');
 perform public.mes_dispatch('saveProfile','{"displayName":"Owner Profile","jobTitle":"OT Owner"}','{"owner":true,"uid":"mes-owner"}');
 assert public.mes_dispatch('getSession','{}',owner)->'user'->>'jobTitle'='OT Owner';
 assert (select count(*)=1 from mes_private.records where collection='users' and data->>'username'='hpham');
 raise notice 'PASS: owner bootstrap, activation/password security, user/admin permissions, self profiles, personal/shared tickets, revocation, resets, expiry, rate limits and Tester';
end $$;
rollback;
